import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, test } from 'vitest';
import { parseStudyConfig } from './parser';
import { ComponentBlock, StudyConfig, WebsiteComponent } from './types';
import { Sequence } from '../store/types';
import { generateSequenceArray } from '../utils/handleRandomSequences';

// Guards the headline study (generated by scripts/build_demo_headline.py): answers from its HTML
// (website) components are only stored when the HTML loads revisit-communicate.js and the config
// declares the posted reactive key; the sequence must follow the Latin-square design.
const publicDir = fileURLToPath(new URL('../../public/', import.meta.url));
const rawConfig = readFileSync(resolve(publicDir, 'demo-headline/config.json'), 'utf-8');
const config = JSON.parse(rawConfig) as StudyConfig;
const websiteComponents = Object.entries(config.components)
  .filter((entry): entry is [string, WebsiteComponent] => entry[1].type === 'website');
const trials = websiteComponents.filter(([, component]) => component.path.includes('trial-stimulus.html'));

type Meta = Record<string, string | number | boolean | null>;
const meta = (name: string) => (config.components[name]?.meta || {}) as Meta;
const htmlFile = (component: WebsiteComponent) => resolve(publicDir, component.path.split('?')[0]);
const flatten = (sequence: Sequence): string[] => sequence.components
  .flatMap((component) => (typeof component === 'string' ? [component] : flatten(component)));

describe('demo-headline config', () => {
  test('passes reVISit config validation', async () => {
    const parsed = await parseStudyConfig(rawConfig);
    expect(parsed.errors).toEqual([]);
  });

  test('every HTML page loads revisit-communicate.js from a path that exists', () => {
    const files = new Set(websiteComponents.map(([, component]) => htmlFile(component)));
    expect(files.size).toBe(2);

    files.forEach((file) => {
      const html = readFileSync(file, 'utf-8');
      const src = html.match(/<script src="([^"]*revisit-communicate\.js)"><\/script>/)?.[1];
      expect(src, file).toBeDefined();
      expect(existsSync(resolve(dirname(file), src || '')), `${file} -> ${src}`).toBe(true);
    });
  });

  test('trial components require the investment choice posted by trial-stimulus.html', () => {
    // 2 arms x (2 practice + 32 conditions x 3 trends + 2 attention checks x 3 trends)
    expect(trials).toHaveLength(208);

    trials.forEach(([name, component]) => {
      expect(component.response, name).toEqual([expect.objectContaining({
        id: 'investment-choice', type: 'reactive', required: true, hidden: true,
      })]);
    });
    expect(readFileSync(htmlFile(trials[0][1]), 'utf-8')).toContain("'investment-choice':");
  });

  test('trial URLs match their meta and every chart exists', () => {
    trials.forEach(([name, component]) => {
      const m = meta(name);
      const params = new URLSearchParams(component.path.split('?')[1]);
      expect(existsSync(resolve(publicDir, 'demo-headline/assets/plots', String(m.chart_file))), name).toBe(true);
      expect(params.get('c'), name).toBe(m.chart_file);
      expect(Number(params.get('sig')), name).toBe(m.base_target_pct);
      expect(Number(params.get('p')), name).toBe(m.option_b_probability);
      expect([...params.keys()].at(-1), name).toBe('p');
      expect(params.get('h'), name).toBe(m.headline_text);
      if (m.signal_ratio && !m.is_attention_check) {
        expect(m.base_target_pct, name).toBeCloseTo(Number(m.signal_ratio) * Number(m.option_b_expected_return_pct), 6);
      }
    });
  });

  test('risk precheck components require the completion key posted by risk-precheck.html', () => {
    const prechecks = websiteComponents.filter(([, component]) => component.path.includes('risk-precheck.html'));
    expect(prechecks.map(([name]) => name).sort()).toEqual(['p25-risk-precheck', 'p55-risk-precheck']);

    prechecks.forEach(([name, component]) => {
      // risk-precheck.html derives its answer keys from the ?p= parameter
      const arm = `p${component.path.match(/\?p=(\d+)/)?.[1]}`;
      expect(component.response, name).toEqual([expect.objectContaining({
        id: `risk-precheck-${arm}-complete`, type: 'reactive', required: true, hidden: true, requiredValue: true,
      })]);

      const html = readFileSync(htmlFile(component), 'utf-8');
      expect(html).toMatch(/const ANSWER_PREFIX = `risk-precheck-\$\{probabilityLevel\}`;/);
      expect(html).toMatch(/\[`\$\{ANSWER_PREFIX\}-complete`\]: !!finalFlag/);
      expect(html).toContain(`${arm}: { label: '${arm.slice(1)}%'`);
    });
  });

  test('final page collects the Prolific ID', () => {
    const { components } = config.sequence as ComponentBlock;
    expect(components[components.length - 1]).toBe('debrief');
    expect(config.components.debrief.response).toContainEqual(expect.objectContaining({
      id: 'prolific_id', type: 'shortText', required: true, paramCapture: 'PROLIFIC_PID',
    }));
  });
});

describe('demo-headline sequences', () => {
  const sequences = generateSequenceArray(config).map(flatten);
  const mainTrials = (sequence: string[]) => sequence.filter((name) => meta(name).list);

  test('each participant sees one arm, 2 practice trials, then 34 trials from one list', () => {
    expect(sequences).toHaveLength(204);
    sequences.forEach((sequence) => {
      const arm = sequence[1].slice(0, 3);
      expect(sequence.slice(0, 5)).toEqual(['consent', `${arm}-introduction`, `${arm}-risk-precheck`, `${arm}-practice-1`, `${arm}-practice-2`]);
      expect(sequence.slice(39)).toEqual(['post-study-free-response', 'post-study-survey', 'debrief', 'end']);

      const block = mainTrials(sequence);
      expect(block).toEqual(sequence.slice(5, 39));
      expect(new Set(block.map((name) => meta(name).probability_arm))).toEqual(new Set([arm]));
      expect(new Set(block.map((name) => meta(name).list)).size).toBe(1);
    });
  });

  test('the 34 trials cover every condition once with no repeated chart or headline', () => {
    sequences.map(mainTrials).forEach((block) => {
      const conditions = block.map((name) => meta(name).condition_id);
      expect(new Set(conditions).size).toBe(34);
      expect(new Set(block.map((name) => meta(name).chart_file)).size).toBe(34);

      const headlines = block.map((name) => meta(name)).filter((m) => m.headline_group === 'ambiguous' || m.headline_group === 'unambiguous');
      expect(new Set(headlines.map((m) => m.headline_text)).size).toBe(16);
      const valences = headlines.map((m) => m.headline_valence);
      expect(valences.filter((v) => v === 'ambiguous')).toHaveLength(8);
      expect(valences.filter((v) => v === 'positive')).toHaveLength(6);
      expect(valences.filter((v) => v === 'negative')).toHaveLength(2);
      headlines.filter((m) => m.headline_group === 'unambiguous')
        .forEach((m) => expect(m.headline_valence).toBe(Number(m.signal_ratio) < 1 ? 'negative' : 'positive'));
    });
  });

  test('history trends are balanced and differ between the two no-headline copies', () => {
    sequences.map(mainTrials).forEach((block) => {
      const conditions = block.map((name) => meta(name)).filter((m) => !m.is_attention_check);
      const counts = ['positive', 'negative', 'flat'].map((t) => conditions.filter((m) => m.history_trend === t).length);
      expect(counts.sort((a, b) => a - b)).toEqual([10, 11, 11]);

      const byCell = (group: string) => Object.fromEntries(conditions.filter((m) => String(m.condition_id).includes(`-${group}-`))
        .map((m) => [String(m.condition_id).replace(`-${group}-`, '-'), m]));
      const [nh1, nh2, amb, unamb] = ['nh1', 'nh2', 'amb', 'unamb'].map(byCell);
      Object.keys(amb).forEach((cell) => {
        expect(nh1[cell].history_trend).not.toBe(nh2[cell].history_trend);
        expect(unamb[cell].history_trend).toBe(amb[cell].history_trend);
        expect(unamb[cell].headline_domain).toBe(amb[cell].headline_domain);
      });
    });
  });

  test('arms and lists are balanced, and each list uses one full balanced Latin square of orders', () => {
    // The trial order as written in config.json must never be shown as-is.
    const listedOrders = ((config.sequence as ComponentBlock).components[1] as ComponentBlock).components
      .flatMap((arm) => ((arm as ComponentBlock).components.at(-1) as ComponentBlock).components)
      .map((list) => (list as ComponentBlock).components);
    expect(listedOrders).toHaveLength(6);
    const groups = new Map<string, string[][]>();
    sequences.map(mainTrials).forEach((block) => {
      const key = `${meta(block[0]).probability_arm}-${meta(block[0]).list}`;
      groups.set(key, [...(groups.get(key) || []), block]);
    });
    expect([...groups.keys()].sort()).toEqual(['p25-1', 'p25-2', 'p25-3', 'p55-1', 'p55-2', 'p55-3']);

    groups.forEach((orders, key) => {
      expect(orders, key).toHaveLength(34);
      // Every trial appears once in every position...
      for (let position = 0; position < 34; position += 1) {
        expect(new Set(orders.map((order) => order[position])).size, key).toBe(34);
      }
      // ...and immediately follows every other trial exactly once (no fixed order or neighbor).
      const pairs = orders.flatMap((order) => order.slice(1).map((name, i) => `${order[i]}>${name}`));
      expect(new Set(pairs).size, key).toBe(34 * 33);
      orders.forEach((order) => expect(listedOrders).not.toContainEqual(order));
    });
  });

  test('across lists every condition appears with every history trend exactly once', () => {
    ['p55', 'p25'].forEach((arm) => {
      const used = sequences.map(mainTrials).flat().filter((name) => name.startsWith(arm));
      const all = trials.map(([name]) => name).filter((name) => name.startsWith(arm) && meta(name).list);
      expect(new Set(used)).toEqual(new Set(all));
      expect(all).toHaveLength(102);
    });
  });
});
